import type { AlarmRecord, DeviceEntity, PlatformRole, SceneDefinition, SpatialTree, UserSession, WorkOrderRecord } from '@pacom/contracts';
import { DEMO_ROLE_PROFILES, E7F_IDS, type PacomDataAdapter } from '../adapters';
import { renderIcon, type IconName } from '../design-system/icons';
import { mountAccountView } from '../features/account/account-view';
import { mountAlarmsView } from '../features/alarms/alarms-view';
import { mountAnalysisView } from '../features/analysis/analysis-view';
import { mountDeploymentView } from '../features/deployment/deployment-view';
import { mountE7FWorkspace } from '../features/e7f-slice/workspace';
import { mountScenesView } from '../features/scenes/scenes-view';
import { mountSettingsView } from '../features/settings/settings-view';

export type WorkspaceRoute =
  | 'home'
  | 'analysis'
  | 'alarms'
  | 'scenes'
  | 'settings'
  | 'deployment'
  | 'account';

interface NavItem {
  id: Exclude<WorkspaceRoute, 'account'>;
  label: string;
  icon: IconName;
}

const SIDEBAR_COLLAPSE_KEY = 'pacom.web.sidebar.collapsed';

/** PACOM 4.07 原版矢量标志（侧栏展开态） */
const PACOM_WORDMARK_SVG = `<svg class="pacom-logo-wordmark" role="img" aria-label="PACOM" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 50">
  <path fill="#202a44" d="M45,17C45,7.61,37.39,0,28,0H0l5,10h23c3.87,0,7,3.13,7,7s-3.13,7-7,7H0v26h10v-16h18c9.39,0,17-7.61,17-17Z"/>
  <polygon fill="#202a44" points="32.25 50 43.66 50 59.75 20.75 75.84 50 87.25 50 59.75 0 32.25 50"/>
  <polygon fill="#202a44" points="208.59 0 192.5 29.25 176.41 0 165 0 192.5 50 210 18.18 210 50 220 50 220 0 208.59 0"/>
  <path fill="#202a44" d="M146.75,0c-13.81,0-25,11.19-25,25s11.19,25,25,25,25-11.19,25-25S160.56,0,146.75,0ZM146.75,40c-8.28,0-15-6.72-15-15s6.72-15,15-15,15,6.72,15,15-6.72,15-15,15Z"/>
  <path fill="#202a44" d="M105.25,40c-8.28,0-15-6.72-15-15s6.72-15,15-15c6.06,0,11.44,2.36,14.81,6.01,1.16-3.28,2.94-6.26,5.19-8.82-5.15-4.45-12.21-7.19-20-7.19-13.81,0-25,11.19-25,25s11.19,25,25,25c7.79,0,14.85-2.74,20-7.19-2.25-2.56-4.03-5.54-5.19-8.82-3.37,3.65-8.75,6.01-14.81,6.01Z"/>
</svg>`;

/** 终版 6 项主导航（第一组 4 项无标题；第二组「配置」2 项） */
const NAV_ITEMS: NavItem[] = [
  { id: 'home', label: '空间总览', icon: 'building-2' },
  { id: 'analysis', label: '数据分析', icon: 'chart-column' },
  { id: 'alarms', label: '告警中心', icon: 'triangle-alert' },
  { id: 'scenes', label: '智能策略', icon: 'sparkles' },
  { id: 'settings', label: '应用设置', icon: 'settings-2' },
  { id: 'deployment', label: '系统部署', icon: 'network' },
];

const ROUTE_TITLES: Record<WorkspaceRoute, string> = {
  home: '空间总览',
  analysis: '数据分析',
  alarms: '告警中心',
  scenes: '智能策略',
  settings: '应用设置',
  deployment: '系统部署',
  account: '机构与账户',
};

interface GlobalDocItem {
  id: string;
  title: string;
  category: string;
  hash: string;
}

const GLOBAL_DOCS_INDEX: GlobalDocItem[] = [
  { id: 'doc-e7f-plan', title: 'E7F 平面竣工图（PDF / DWG）', category: '图纸', hash: '#deployment?sec=floors' },
  { id: 'doc-e7f-hvac', title: 'E7F 暖通末端 FCU/VAV 原理图', category: '图纸', hash: '#deployment?sec=floors' },
  { id: 'doc-e7f-knx', title: 'KNX / DALI-2 照明回路点位表', category: '点位表', hash: '#deployment?sec=floors' },
  { id: 'doc-e7f-gw', title: '边缘网关与控制器维保手册', category: '手册', hash: '#deployment?sec=floors' },
];

function parseRoute(): WorkspaceRoute {
  const hash = window.location.hash.replace(/^#\/?/, '').split('?')[0] ?? '';
  if (hash in ROUTE_TITLES) return hash as WorkspaceRoute;
  return 'home';
}

function escapeHtml(text: string): string {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

export async function mountAppShell(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  initialSession: UserSession,
  onLoggedOut: () => void
): Promise<void> {
  root.classList.remove('bare-login');

  let session = initialSession;
  let route: WorkspaceRoute = parseRoute();
  let collapsed = localStorage.getItem(SIDEBAR_COLLAPSE_KEY) === '1';
  let mobileOpen = false;
  let orgMenuOpen = false;
  let navSearch = '';
  let cmdOpen = false;
  let activeAlarmCount = 0;
  let searchIndex: {
    devices: DeviceEntity[];
    zones: SpatialTree['zones'];
    alarms: AlarmRecord[];
    workOrders: WorkOrderRecord[];
    scenes: SceneDefinition[];
  } = { devices: [], zones: [], alarms: [], workOrders: [], scenes: [] };

  const isDemo = adapter.mode === 'demo' && typeof adapter.switchDemoRole === 'function';

  async function refreshGlobalIndex(): Promise<void> {
    try {
      const [tree, devices, alarms, workOrders, scenes] = await Promise.all([
        adapter.getSpatialTree(),
        adapter.getFloorDevices(E7F_IDS.floorId).catch(() => []),
        adapter.listAlarms(E7F_IDS.floorId).catch(() => []),
        adapter.listWorkOrders(E7F_IDS.floorId).catch(() => []),
        adapter.listScenes(E7F_IDS.floorId).catch(() => []),
      ]);
      searchIndex = { devices, zones: tree.zones, alarms, workOrders, scenes };
      activeAlarmCount = alarms.filter((a) => a.status === 'active').length;
      updateNavListOnly();
    } catch {
      // 忽略索引加载失败
    }
  }

  function renderNavListHtml(): string {
    return NAV_ITEMS.map(
      (item) => `
        ${item.id === 'settings' ? '<div class="pacom-nav-group-title">配置</div><div class="pacom-nav-group-sep" role="separator"></div>' : ''}
        <button type="button" class="pacom-nav-item" data-route="${item.id}" aria-current="${route === item.id ? 'page' : 'false'}" title="${item.label}">
          ${renderIcon(item.icon, 16, 'pacom-nav-icon')}
          <span class="pacom-nav-label">${item.label}</span>
          ${item.id === 'alarms' && activeAlarmCount > 0 ? `<span class="pacom-nav-count" title="待处理告警 ${activeAlarmCount} 条">${activeAlarmCount}</span>` : ''}
        </button>`
    ).join('');
  }

  function renderCmdResultsHtml(): string {
    const q = navSearch.trim().toLowerCase();
    const menuHits = q ? NAV_ITEMS.filter((n) => n.label.toLowerCase().includes(q)).slice(0, 4) : NAV_ITEMS;
    const devHits = q
      ? searchIndex.devices.filter((d) => `${d.name} ${d.id} ${d.category}`.toLowerCase().includes(q)).slice(0, 5)
      : searchIndex.devices.slice(0, 3);
    const zoneHits = q ? searchIndex.zones.filter((z) => z.name.toLowerCase().includes(q)).slice(0, 3) : [];
    const alarmHits = q
      ? searchIndex.alarms.filter((a) => `${a.title} ${a.message} ${a.id}`.toLowerCase().includes(q)).slice(0, 4)
      : searchIndex.alarms.filter((a) => a.status === 'active').slice(0, 2);
    const woHits = q
      ? searchIndex.workOrders.filter((w) => `${w.title} ${w.id}`.toLowerCase().includes(q)).slice(0, 3)
      : [];
    const sceneHits = q
      ? searchIndex.scenes.filter((s) => `${s.name} ${s.description}`.toLowerCase().includes(q)).slice(0, 3)
      : [];
    const docHits = q
      ? GLOBAL_DOCS_INDEX.filter((doc) => `${doc.title} ${doc.category}`.toLowerCase().includes(q)).slice(0, 4)
      : GLOBAL_DOCS_INDEX.slice(0, 2);

    const sections: string[] = [];
    if (devHits.length) {
      sections.push(
        `<div class="pacom-search-group">${q ? '设备（空间总览）' : '常用设备直达'}</div>` +
          devHits
            .map(
              (d) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="#home?device=${encodeURIComponent(d.id)}"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(d.name)}</span><span class="pacom-badge ${d.connectivity === 'online' ? 'pacom-badge--online' : 'pacom-badge--critical'}">${d.connectivity === 'online' ? '在线' : '离线'}</span></button>`
            )
            .join('')
      );
    }
    if (zoneHits.length) {
      sections.push(
        `<div class="pacom-search-group">功能区</div>` +
          zoneHits
            .map(
              (z) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="#home?zone=${encodeURIComponent(z.id)}"><span>${escapeHtml(z.name)}</span><span class="pacom-badge pacom-badge--neutral">区域</span></button>`
            )
            .join('')
      );
    }
    if (alarmHits.length) {
      sections.push(
        `<div class="pacom-search-group">${q ? '告警' : '待处理告警'}</div>` +
          alarmHits
            .map(
              (a) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="#alarms?alarm=${encodeURIComponent(a.id)}"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(a.title)}</span><span class="pacom-badge pacom-badge--warning">${a.status === 'active' ? '待处理' : '已确认'}</span></button>`
            )
            .join('')
      );
    }
    if (woHits.length) {
      sections.push(
        `<div class="pacom-search-group">运维工单</div>` +
          woHits
            .map(
              (w) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="#alarms?wo=${encodeURIComponent(w.id)}"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(w.title)}</span><span class="pacom-badge pacom-badge--accent">工单</span></button>`
            )
            .join('')
      );
    }
    if (sceneHits.length) {
      sections.push(
        `<div class="pacom-search-group">智能策略</div>` +
          sceneHits
            .map(
              (s) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="#scenes"><span>${escapeHtml(s.name)}</span><span class="pacom-badge pacom-badge--neutral">场景</span></button>`
            )
            .join('')
      );
    }
    if (docHits.length) {
      sections.push(
        `<div class="pacom-search-group">图纸与工程文档</div>` +
          docHits
            .map(
              (doc) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="${doc.hash}"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(doc.title)}</span><span class="pacom-badge pacom-badge--neutral">${escapeHtml(doc.category)}</span></button>`
            )
            .join('')
      );
    }
    if (menuHits.length) {
      sections.push(
        `<div class="pacom-search-group">工作区</div>` +
          menuHits
            .map(
              (m) =>
                `<button type="button" class="pacom-search-hit" data-search-hash="#${m.id}"><span style="display:inline-flex; align-items:center; gap:8px;">${renderIcon(m.icon, 14)}${escapeHtml(m.label)}</span><span class="pacom-badge pacom-badge--neutral">前往</span></button>`
            )
            .join('')
      );
    }
    if (!sections.length) {
      return `<div class="pacom-nav-empty">未找到与「${escapeHtml(navSearch)}」匹配的设备、区域、告警、工单或图纸</div>`;
    }
    return sections.join('');
  }

  function bindCmdHitEvents(container: Element): void {
    container.querySelectorAll<HTMLButtonElement>('[data-search-hash]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const targetHash = btn.dataset.searchHash || '#home';
        cmdOpen = false;
        navSearch = '';
        updateCmdModalOnly();
        mobileOpen = false;
        if (window.location.hash === targetHash) {
          route = parseRoute();
          void renderFrame(true);
        } else {
          window.location.hash = targetHash;
        }
      });
    });
  }

  function updateCmdModalOnly(): void {
    root.querySelector('[data-role="cmd-scrim"]')?.remove();
    if (!cmdOpen) return;
    const scrim = document.createElement('div');
    scrim.className = 'pacom-cmd-scrim';
    scrim.dataset.role = 'cmd-scrim';
    scrim.innerHTML = `
      <div class="pacom-cmd-modal" role="dialog" aria-modal="true" aria-label="全局快速搜索">
        <div class="pacom-cmd-head">
          ${renderIcon('search', 16)}
          <input class="pacom-cmd-input" name="cmdSearch" data-role="cmd-input" type="search" placeholder="搜索设备、空间、告警、工单、图纸或工作区…" value="${escapeHtml(navSearch)}" autocomplete="off" />
          <kbd class="pacom-kbd">Esc</kbd>
        </div>
        <div class="pacom-cmd-body" data-role="cmd-body">
          ${renderCmdResultsHtml()}
        </div>
      </div>
    `;
    root.appendChild(scrim);

    scrim.addEventListener('click', (e) => {
      if (e.target === scrim) {
        cmdOpen = false;
        updateCmdModalOnly();
      }
    });

    const input = scrim.querySelector<HTMLInputElement>('[data-role="cmd-input"]');
    const body = scrim.querySelector<HTMLElement>('[data-role="cmd-body"]');
    if (body) bindCmdHitEvents(body);
    input?.focus();
    input?.addEventListener('input', (e) => {
      navSearch = (e.currentTarget as HTMLInputElement).value;
      if (body) {
        body.innerHTML = renderCmdResultsHtml();
        bindCmdHitEvents(body);
      }
    });
  }

  function renderOrgPopoverHtml(): string {
    if (!orgMenuOpen) return '';
    const avatarChar = session.displayName.slice(0, 1) || 'U';
    return `
      <div class="pacom-org-popover ${collapsed ? 'is-collapsed-anchor' : ''}" role="menu" aria-label="机构与账户" data-role="org-popover">
        <button type="button" class="pacom-pop-item pacom-pop-item--tall" role="menuitem" data-pop-act="go-account">
          <span class="pacom-org-mark" aria-hidden="true"><img src="./media/gzlab-mark.svg" alt="" /></span>
          <span class="pacom-pop-text">
            <b>广州国家实验室</b>
            <small>${escapeHtml(session.roleLabel)}</small>
          </span>
          ${renderIcon('check', 16, 'pacom-pop-check')}
        </button>

        <button type="button" class="pacom-pop-item" role="menuitem" data-pop-act="go-account">
          <span class="pacom-pop-icon" aria-hidden="true">${renderIcon('settings', 16)}</span>
          <span class="pacom-pop-text">机构设置</span>
        </button>

        <hr class="pacom-pop-hr" />

        <button type="button" class="pacom-pop-item pacom-pop-item--tall" role="menuitem" data-pop-act="go-account">
          <span class="pacom-pop-avatar" aria-hidden="true">${escapeHtml(avatarChar)}</span>
          <span class="pacom-pop-text">
            <b>${escapeHtml(session.displayName)}</b>
            <small>我的账户与权限范围</small>
          </span>
        </button>

        ${
          isDemo
            ? `
            <hr class="pacom-pop-hr" />
            <div class="pacom-pop-section-label">切换视角</div>
            <div class="pacom-pop-role-list">
              ${(Object.keys(DEMO_ROLE_PROFILES) as PlatformRole[])
                .map((r) => {
                  const p = DEMO_ROLE_PROFILES[r];
                  const active = r === session.role;
                  return `
                    <button type="button" class="pacom-pop-item" role="menuitemradio" aria-checked="${active}" data-pop-role="${r}">
                      <span class="pacom-pop-text">
                        <b>${escapeHtml(p.roleLabel)}</b>
                        <small>${escapeHtml(p.displayName)}</small>
                      </span>
                      ${active ? renderIcon('check', 16, 'pacom-pop-check') : ''}
                    </button>`;
                })
                .join('')}
            </div>`
            : ''
        }

        <hr class="pacom-pop-hr" />

        <button type="button" class="pacom-pop-item pacom-pop-item--danger" role="menuitem" data-pop-act="logout">
          <span class="pacom-pop-icon" aria-hidden="true">${renderIcon('log-out', 16)}</span>
          <span class="pacom-pop-text">退出登录</span>
        </button>
      </div>
    `;
  }

  async function renderStage(stage: HTMLElement): Promise<void> {
    document.title = `${ROUTE_TITLES[route]} · PACOM Station`;
    switch (route) {
      case 'home':
        await mountE7FWorkspace(stage, adapter, session);
        return;
      case 'analysis':
        await mountAnalysisView(stage, adapter, session);
        return;
      case 'alarms':
        await mountAlarmsView(stage, adapter, session);
        return;
      case 'scenes':
        await mountScenesView(stage, adapter, session);
        return;
      case 'settings':
        await mountSettingsView(stage, adapter, session);
        return;
      case 'deployment':
        await mountDeploymentView(stage, adapter, session);
        return;
      case 'account':
        await mountAccountView(
          stage,
          adapter,
          session,
          (next) => {
            session = next;
            void renderFrame(true);
          },
          handleLogout
        );
        return;
    }
  }

  async function handleLogout(): Promise<void> {
    orgMenuOpen = false;
    mobileOpen = false;
    cmdOpen = false;
    cleanupListeners();
    try {
      await adapter.logout();
    } finally {
      window.location.hash = '#login';
      onLoggedOut();
    }
  }

  function updateNavListOnly(): void {
    const listEl = root.querySelector<HTMLElement>('[data-role="nav-list"]');
    if (!listEl) return;
    listEl.innerHTML = renderNavListHtml();
    bindNavItemEvents();
  }

  function updateOrgPopoverOnly(): void {
    root.querySelector('[data-role="org-popover"]')?.remove();
    const orgBtn = root.querySelector<HTMLButtonElement>('[data-role="org-menu-btn"]');
    if (orgBtn) orgBtn.setAttribute('aria-expanded', String(orgMenuOpen));
    if (!orgMenuOpen) return;

    const wrapper = document.createElement('div');
    wrapper.innerHTML = renderOrgPopoverHtml().trim();
    const pop = wrapper.firstElementChild;
    if (pop) {
      root.appendChild(pop);
      bindOrgPopoverEvents();
    }
  }

  function bindNavItemEvents(): void {
    root.querySelectorAll<HTMLButtonElement>('[data-route]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const nextRoute = btn.dataset.route as WorkspaceRoute;
        if (nextRoute === route && !mobileOpen) return;
        route = nextRoute;
        mobileOpen = false;
        orgMenuOpen = false;
        window.location.hash = `#${route}`;
        void renderFrame(true);
      });
    });
  }

  function bindOrgPopoverEvents(): void {
    root.querySelectorAll<HTMLButtonElement>('[data-pop-act="go-account"]').forEach((btn) => {
      btn.addEventListener('click', () => {
        orgMenuOpen = false;
        mobileOpen = false;
        route = 'account';
        window.location.hash = '#account';
        void renderFrame(true);
      });
    });

    root.querySelector<HTMLButtonElement>('[data-pop-act="logout"]')?.addEventListener('click', () => {
      void handleLogout();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-pop-role]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!adapter.switchDemoRole) return;
        const role = btn.dataset.popRole as PlatformRole;
        orgMenuOpen = false;
        mobileOpen = false;
        session = await adapter.switchDemoRole(role);
        await renderFrame(true);
      });
    });
  }

  async function renderFrame(reloadStage: boolean): Promise<void> {
    const existingStage = root.querySelector<HTMLElement>('[data-role="main-stage"]');

    if (!reloadStage && existingStage) {
      const rail = root.querySelector<HTMLElement>('.pacom-nav-rail');
      if (rail) {
        rail.classList.toggle('is-collapsed', collapsed);
        rail.classList.toggle('is-mobile-open', mobileOpen);
      }
      const scrim = root.querySelector<HTMLElement>('[data-role="mobile-scrim"]');
      if (scrim) scrim.classList.toggle('is-open', mobileOpen);
      updateOrgPopoverOnly();
      return;
    }

    root.innerHTML = `
      <div class="pacom-app-frame">
        <header class="pacom-mobile-bar">
          <button type="button" class="pacom-mobile-menu-btn" data-role="mobile-menu-btn" aria-label="打开导航菜单">
            ${renderIcon('menu', 20)}
          </button>
          <h1 class="pacom-mobile-title">${ROUTE_TITLES[route]}</h1>
          <span class="pacom-badge pacom-badge--neutral">${escapeHtml(session.roleLabel)}</span>
        </header>

        <div class="pacom-mobile-scrim ${mobileOpen ? 'is-open' : ''}" data-role="mobile-scrim"></div>

        <aside class="pacom-nav-rail ${collapsed ? 'is-collapsed' : ''} ${mobileOpen ? 'is-mobile-open' : ''}" aria-label="主导航">
          <div class="pacom-nav-brand">
            <div class="pacom-nav-logo">${PACOM_WORDMARK_SVG}</div>
            <button type="button" class="pacom-collapse-btn" data-role="toggle-sidebar" title="${collapsed ? '展开侧栏' : '收起侧栏'}" aria-label="${collapsed ? '展开侧栏' : '收起侧栏'}">
              ${renderIcon('panel-left', 16)}
            </button>
          </div>

          <button type="button" class="pacom-search-trigger" data-role="open-cmd" title="快速搜索（⌘K）" aria-label="打开全局快速搜索">
            ${renderIcon('search', 16, 'pacom-nav-icon')}
            <span class="pacom-search-trigger-label">搜索</span>
            <kbd class="pacom-kbd">⌘K</kbd>
          </button>

          <nav class="pacom-nav-list" data-role="nav-list">
            ${renderNavListHtml()}
          </nav>

          <div class="pacom-nav-footer">
            <button type="button" class="pacom-org-btn ${route === 'account' ? 'is-active' : ''}" data-role="org-menu-btn" aria-haspopup="menu" aria-expanded="${orgMenuOpen}" title="广州国家实验室 · ${escapeHtml(session.displayName)}">
              <span class="pacom-org-mark" aria-hidden="true"><img src="./media/gzlab-mark.svg" alt="" /></span>
              <span class="pacom-org-name">广州国家实验室</span>
              ${renderIcon('chevrons-up-down', 14, 'pacom-org-arrows')}
            </button>
          </div>
        </aside>

        <div class="pacom-main-stage" data-role="main-stage"></div>
      </div>
    `;

    root.querySelector<HTMLButtonElement>('[data-role="toggle-sidebar"]')?.addEventListener('click', () => {
      collapsed = !collapsed;
      orgMenuOpen = false;
      localStorage.setItem(SIDEBAR_COLLAPSE_KEY, collapsed ? '1' : '0');
      const rail = root.querySelector<HTMLElement>('.pacom-nav-rail');
      const btn = root.querySelector<HTMLButtonElement>('[data-role="toggle-sidebar"]');
      if (rail) rail.classList.toggle('is-collapsed', collapsed);
      if (btn) {
        btn.title = collapsed ? '展开侧栏' : '收起侧栏';
        btn.setAttribute('aria-label', btn.title);
        btn.innerHTML = renderIcon('panel-left', 16);
      }
      updateOrgPopoverOnly();
    });

    root.querySelector<HTMLButtonElement>('[data-role="open-cmd"]')?.addEventListener('click', () => {
      orgMenuOpen = false;
      updateOrgPopoverOnly();
      cmdOpen = true;
      updateCmdModalOnly();
    });

    root.querySelector<HTMLButtonElement>('[data-role="mobile-menu-btn"]')?.addEventListener('click', () => {
      mobileOpen = !mobileOpen;
      void renderFrame(false);
    });

    root.querySelector<HTMLElement>('[data-role="mobile-scrim"]')?.addEventListener('click', () => {
      mobileOpen = false;
      orgMenuOpen = false;
      void renderFrame(false);
    });

    root.querySelector<HTMLButtonElement>('[data-role="org-menu-btn"]')?.addEventListener('click', (e) => {
      e.stopPropagation();
      orgMenuOpen = !orgMenuOpen;
      updateOrgPopoverOnly();
    });

    bindNavItemEvents();
    updateOrgPopoverOnly();
    updateCmdModalOnly();

    const stage = root.querySelector<HTMLElement>('[data-role="main-stage"]');
    if (stage) await renderStage(stage);
  }

  const onDocClick = (e: MouseEvent) => {
    const target = e.target as HTMLElement | null;
    if (orgMenuOpen && !target?.closest('[data-role="org-popover"]') && !target?.closest('[data-role="org-menu-btn"]')) {
      orgMenuOpen = false;
      updateOrgPopoverOnly();
    }
  };

  const onDocKeydown = (e: KeyboardEvent) => {
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      orgMenuOpen = false;
      updateOrgPopoverOnly();
      cmdOpen = !cmdOpen;
      updateCmdModalOnly();
      return;
    }
    if (e.key === 'Escape') {
      if (cmdOpen) {
        cmdOpen = false;
        updateCmdModalOnly();
      } else if (orgMenuOpen) {
        orgMenuOpen = false;
        updateOrgPopoverOnly();
      } else if (mobileOpen) {
        mobileOpen = false;
        void renderFrame(false);
      }
    }
  };

  const onHashChange = () => {
    const next = parseRoute();
    route = next;
    orgMenuOpen = false;
    mobileOpen = false;
    cmdOpen = false;
    void renderFrame(true);
    void refreshGlobalIndex();
  };

  function cleanupListeners(): void {
    document.removeEventListener('click', onDocClick);
    document.removeEventListener('keydown', onDocKeydown);
    window.removeEventListener('hashchange', onHashChange);
  }

  document.addEventListener('click', onDocClick);
  document.addEventListener('keydown', onDocKeydown);
  window.addEventListener('hashchange', onHashChange);

  await renderFrame(true);
  void refreshGlobalIndex();
}
