import type { AuditLogEntry, OrgMember, PlatformRole, UserSession } from '@pacom/contracts';
import { DEMO_ROLE_PROFILES, type PacomDataAdapter } from '../../adapters';

type AccountTab = 'profile' | 'members' | 'audit';
type MembersSubTab = 'directory' | 'groups';

interface WorkgroupItem {
  id: string;
  name: string;
  defaultRoleLabel: string;
  locationScope: string;
  memberCount: number;
  membersSummary: string;
  notifyChannel: string;
}

const WORKGROUPS: WorkgroupItem[] = [
  {
    id: 'wg-hvac',
    name: '暖通运维组',
    defaultRoleLabel: '运行值班员',
    locationScope: '广实2号园 / E栋 5F–7F（HVAC、FCU 与 VAV 系统）',
    memberCount: 3,
    membersSummary: '陈值班、林工、周工',
    notifyChannel: '站内 + 短信',
  },
  {
    id: 'wg-elec',
    name: '强电照明组',
    defaultRoleLabel: '运行值班员',
    locationScope: '广实2号园 / E栋全楼照明与配电回路',
    memberCount: 2,
    membersSummary: '黄工、刘工',
    notifyChannel: '站内 + 邮件',
  },
  {
    id: 'wg-property',
    name: '园区物业值班组',
    defaultRoleLabel: '只读访客 / 值班巡检',
    locationScope: '广实2号园 / 全园区公共空间与值班台',
    memberCount: 4,
    membersSummary: '张班长、王巡检、赵巡检、吴值守',
    notifyChannel: '站内 + 每日晨报',
  },
];

export async function mountAccountView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession,
  onRoleChanged: (next: UserSession) => void,
  onLoggedOut: () => void
): Promise<void> {
  let tab: AccountTab = 'profile';
  let membersSubTab: MembersSubTab = 'directory';
  let members: OrgMember[] = await adapter.listOrgMembers();
  let logs: AuditLogEntry[] = await adapter.listAuditLogs();
  let memberSearch = '';
  let roleFilter = 'all';
  let auditFilter: 'all' | 'success' | 'denied' = 'all';
  let auditActionCat: 'all' | 'control' | 'alarm' | 'deploy' = 'all';
  let showInviteForm = false;
  let showNewGroupForm = false;
  let profileName = session.displayName;
  let profileTitle =
    session.role === 'org_admin' || session.role === 'project_admin'
      ? '设施运维总监'
      : session.role === 'commissioning_engineer'
        ? '楼宇自控部署工程师'
        : session.role === 'facility_operator'
          ? '暖通运行值班工程师'
          : '园区巡检成员';
  let profilePhone = '138-0013-8072';
  let profileNotice = '';
  let errorMsg = '';

  async function refresh(): Promise<void> {
    [members, logs] = await Promise.all([adapter.listOrgMembers(), adapter.listAuditLogs()]);
    render();
  }

  function render(): void {
    const isDemo = adapter.mode === 'demo' && typeof adapter.switchDemoRole === 'function';
    const mq = memberSearch.trim().toLowerCase();
    const visibleMembers = members.filter((m) => {
      if (roleFilter !== 'all' && m.role !== roleFilter) return false;
      if (!mq) return true;
      return `${m.displayName} ${m.email} ${m.roleLabel} ${m.scopeSummary}`.toLowerCase().includes(mq);
    });

    const visibleLogs = logs.filter((l) => {
      if (auditFilter === 'success' && l.result !== 'success') return false;
      if (auditFilter === 'denied' && l.result === 'success') return false;
      if (auditActionCat !== 'all') {
        const txt = `${l.action} ${l.target}`.toLowerCase();
        if (auditActionCat === 'control' && !txt.includes('control') && !txt.includes('scene') && !txt.includes('控制')) return false;
        if (auditActionCat === 'alarm' && !txt.includes('alarm') && !txt.includes('work') && !txt.includes('告警')) return false;
        if (auditActionCat === 'deploy' && !txt.includes('deploy') && !txt.includes('plan') && !txt.includes('hardware') && !txt.includes('部署')) return false;
      }
      return true;
    });

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <div style="display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
              <h1 class="pacom-title">机构与账户</h1>
              <div class="pacom-tabs" role="tablist" aria-label="机构与账户视图">
                <button class="pacom-tab" role="tab" aria-selected="${tab === 'profile'}" data-atab="profile">我的账户与权限</button>
                <button class="pacom-tab" role="tab" aria-selected="${tab === 'members'}" data-atab="members">成员与角色（${members.length}）</button>
                <button class="pacom-tab" role="tab" aria-selected="${tab === 'audit'}" data-atab="audit">操作审计日志（${logs.length}）</button>
              </div>
            </div>
            <div class="pacom-header-meta">
              <span class="pacom-badge pacom-badge--neutral">广州国家实验室</span>
              <span class="pacom-badge pacom-badge--accent">${session.roleLabel}</span>
            </div>
          </div>
        </header>

        <div class="pacom-content-page" style="padding:8px 6px 32px;">
          <div style="width:100%; max-width:960px; margin:0 auto; display:flex; flex-direction:column; gap:20px;">
            ${profileNotice ? `<div class="pacom-banner pacom-banner--ok"><span class="pacom-banner-title">${profileNotice}</span></div>` : ''}
            ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}
            ${
              tab === 'profile'
                ? `
                <section class="pacom-section">
                  <div class="pacom-section-head">
                    <h2 class="pacom-section-title">个人资料与授权摘要</h2>
                    <span class="pacom-badge pacom-badge--online">${session.roleLabel}</span>
                  </div>
                  <form class="pacom-settings-card" data-role="profile-form">
                    <div class="pacom-setting-row">
                      <div class="pacom-setting-meta">
                        <span class="pacom-setting-title">显示姓名与岗位</span>
                        <span class="pacom-setting-desc">账号 ID：${session.userId} · 所属机构：广州国家实验室</span>
                      </div>
                      <div class="pacom-setting-control" style="flex-wrap:wrap;">
                        <input class="pacom-input" style="width:150px;" name="displayName" value="${profileName}" aria-label="显示姓名" required />
                        <input class="pacom-input" style="width:180px;" name="jobTitle" value="${profileTitle}" aria-label="岗位职务" />
                      </div>
                    </div>
                    <div class="pacom-setting-row">
                      <div class="pacom-setting-meta">
                        <span class="pacom-setting-title">告警接收手机号（SMS）</span>
                        <span class="pacom-setting-desc">用于接收 P1 严重告警短信推送与工单升级提醒</span>
                      </div>
                      <div class="pacom-setting-control">
                        <input class="pacom-input" style="width:180px;" name="phone" value="${profilePhone}" placeholder="138-xxxx-xxxx" aria-label="手机号" />
                        <button type="submit" class="pacom-btn pacom-btn--primary">保存资料</button>
                      </div>
                    </div>
                    <div class="pacom-setting-row">
                      <div class="pacom-setting-meta">
                        <span class="pacom-setting-title">楼层与操作权限</span>
                        <span class="pacom-setting-desc">
                          已授权楼层 ${session.scope.allowedFloorIds.length} 层 · 设备控制：${session.scope.canControlDevices ? '允许' : '只读'} · 部署编辑：${session.scope.canEditDeployment ? '允许' : '只读'}
                        </span>
                      </div>
                    </div>
                  </form>
                </section>

                ${
                  isDemo
                    ? `
                    <section class="pacom-section">
                      <div class="pacom-section-head">
                        <h2 class="pacom-section-title">切换视角</h2>
                      </div>
                      <div class="pacom-role-grid">
                        ${(Object.keys(DEMO_ROLE_PROFILES) as PlatformRole[])
                          .map((role) => {
                            const p = DEMO_ROLE_PROFILES[role];
                            return `
                              <button class="pacom-role-card ${role === session.role ? 'is-active' : ''}" data-switch-role="${role}">
                                <strong style="font-weight:500;">${p.roleLabel}</strong>
                                <span class="pacom-row-sub">${p.displayName}</span>
                                <span class="pacom-row-sub">授权楼层 ${p.scope.allowedFloorIds.length} 层 · 部署编辑：${p.scope.canEditDeployment ? '是' : '否'}</span>
                              </button>`;
                          })
                          .join('')}
                      </div>
                    </section>`
                    : ''
                }

                <section class="pacom-section">
                  <h2 class="pacom-section-title">会话安全</h2>
                  <div class="pacom-settings-card">
                    <div class="pacom-setting-row">
                      <div class="pacom-setting-meta">
                        <span class="pacom-setting-title">退出当前账号</span>
                        <span class="pacom-setting-desc">退出后将清除本机登录态并返回 PACOM Station 登录页</span>
                      </div>
                      <div class="pacom-setting-control">
                        <button class="pacom-btn pacom-btn--danger" data-role="logout-btn">退出登录</button>
                      </div>
                    </div>
                  </div>
                </section>`
                : tab === 'members'
                  ? `
                  ${
                    showInviteForm
                      ? `
                      <section class="pacom-section">
                        <h2 class="pacom-section-title">邀请新成员</h2>
                        <form class="pacom-settings-card" data-role="invite-form">
                          <div class="pacom-setting-row">
                            <div class="pacom-setting-meta">
                              <span class="pacom-setting-title">成员邮箱与角色</span>
                              <span class="pacom-setting-desc">受邀成员将按角色获得对应项目与楼层的默认授权范围</span>
                            </div>
                            <div class="pacom-setting-control" style="flex-wrap:wrap;">
                              <input class="pacom-input" style="width:220px;" name="email" type="email" placeholder="colleague@gzlab.ac.cn" required />
                              <select class="pacom-select" name="role">
                                ${(Object.keys(DEMO_ROLE_PROFILES) as PlatformRole[])
                                  .map((r) => `<option value="${r}">${DEMO_ROLE_PROFILES[r].roleLabel}</option>`)
                                  .join('')}
                              </select>
                              <button class="pacom-btn pacom-btn--primary" type="submit">发送邀请</button>
                            </div>
                          </div>
                        </form>
                      </section>`
                      : ''
                  }

                  <section class="pacom-section">
                    <div class="pacom-section-head">
                      <div style="display:flex; align-items:center; gap:12px; flex-wrap:wrap;">
                        <h2 class="pacom-section-title">${membersSubTab === 'directory' ? '机构成员目录' : '工作组与空间授权（Groups & Scope）'}</h2>
                        <div class="pacom-tabs" role="tablist" aria-label="成员与工作组切换">
                          <button type="button" class="pacom-tab" role="tab" aria-selected="${membersSubTab === 'directory'}" data-msub="directory">成员目录（${members.length}）</button>
                          <button type="button" class="pacom-tab" role="tab" aria-selected="${membersSubTab === 'groups'}" data-msub="groups">工作组（${WORKGROUPS.length}）</button>
                        </div>
                      </div>
                      <span class="pacom-row-sub">${membersSubTab === 'directory' ? `当前显示 ${visibleMembers.length} 人` : '按空间边界与值班组统一分派告警与工单'}</span>
                    </div>
                    ${
                      membersSubTab === 'directory'
                        ? `
                        <div class="pacom-table-card">
                          <div class="pacom-table-toolbar">
                            <div class="pacom-table-toolbar-group" style="flex:1; min-width:220px;">
                              <input class="pacom-input" name="memberSearch" style="max-width:260px;" data-member-search placeholder="搜索姓名、邮箱或授权范围…" value="${memberSearch}" />
                              <select class="pacom-select" name="memberRoleFilter" data-role-filter>
                                <option value="all" ${roleFilter === 'all' ? 'selected' : ''}>全部角色</option>
                                ${(Object.keys(DEMO_ROLE_PROFILES) as PlatformRole[])
                                  .map((r) => `<option value="${r}" ${roleFilter === r ? 'selected' : ''}>${DEMO_ROLE_PROFILES[r].roleLabel}</option>`)
                                  .join('')}
                              </select>
                            </div>
                            <button class="pacom-btn pacom-btn--primary" data-toggle-invite="1">
                              ${showInviteForm ? '收起邀请' : '+ 邀请成员'}
                            </button>
                          </div>
                          <div class="pacom-table-wrap">
                            <table class="pacom-table">
                              <thead>
                                <tr>
                                  <th>成员</th>
                                  <th>角色</th>
                                  <th>授权范围</th>
                                  <th>状态</th>
                                </tr>
                              </thead>
                              <tbody>
                                ${visibleMembers
                                  .map(
                                    (m) => `
                                    <tr>
                                      <td>
                                        <div style="display:flex; align-items:center; gap:10px;">
                                          <span class="pacom-pop-avatar">${m.displayName.slice(0, 1)}</span>
                                          <div>
                                            <div style="font-weight:500;">${m.displayName}</div>
                                            <div class="pacom-row-sub">${m.email}</div>
                                          </div>
                                        </div>
                                      </td>
                                      <td><span class="pacom-badge pacom-badge--neutral">${m.roleLabel}</span></td>
                                      <td><span class="pacom-row-sub">${m.scopeSummary}</span></td>
                                      <td>
                                        <span class="pacom-badge ${m.status === 'active' ? 'pacom-badge--online' : 'pacom-badge--accent'}">
                                          ${m.status === 'active' ? '正常' : m.status}
                                        </span>
                                      </td>
                                    </tr>`
                                  )
                                  .join('')}
                              </tbody>
                            </table>
                          </div>
                        </div>`
                        : `
                        ${
                          showNewGroupForm
                            ? `
                            <form class="pacom-settings-card" data-role="new-group-form" style="margin-bottom:10px;">
                              <div class="pacom-setting-row" style="display:grid; grid-template-columns:140px 130px 1fr auto; gap:8px; align-items:center;">
                                <input class="pacom-input" name="wgName" placeholder="工作组名称" required />
                                <select class="pacom-select" name="wgRole">
                                  <option value="运行值班员">运行值班员</option>
                                  <option value="部署工程师">部署工程师</option>
                                  <option value="只读访客">只读访客</option>
                                </select>
                                <input class="pacom-input" name="wgScope" placeholder="授权空间边界（如：广实2号园 / E栋 7F）" required />
                                <button class="pacom-btn pacom-btn--primary" type="submit">创建工作组</button>
                              </div>
                            </form>`
                            : ''
                        }
                        <div class="pacom-table-card">
                          <div class="pacom-table-toolbar">
                            <span class="pacom-row-sub">工作组同时用于「应用设置 → 消息通知」的告警分流与自动派单</span>
                            <button type="button" class="pacom-btn pacom-btn--primary" data-toggle-new-group="1">${showNewGroupForm ? '收起表单' : '+ 新建工作组'}</button>
                          </div>
                          <div class="pacom-table-wrap">
                            <table class="pacom-table">
                              <thead>
                                <tr>
                                  <th>工作组名称</th>
                                  <th>默认角色</th>
                                  <th>授权空间边界（Location Scope）</th>
                                  <th>成员规模</th>
                                  <th>默认告警通道</th>
                                </tr>
                              </thead>
                              <tbody>
                                ${WORKGROUPS.map(
                                  (wg) => `
                                  <tr>
                                    <td>
                                      <div style="font-weight:500;">${wg.name}</div>
                                      <div class="pacom-row-sub">${wg.membersSummary}</div>
                                    </td>
                                    <td><span class="pacom-badge pacom-badge--neutral">${wg.defaultRoleLabel}</span></td>
                                    <td><span class="pacom-row-sub">${wg.locationScope}</span></td>
                                    <td><strong>${wg.memberCount}</strong> 人</td>
                                    <td><span class="pacom-badge pacom-badge--accent">${wg.notifyChannel}</span></td>
                                  </tr>`
                                ).join('')}
                              </tbody>
                            </table>
                          </div>
                        </div>`
                    }
                  </section>`
                  : `
                  <section class="pacom-section">
                    <div class="pacom-section-head">
                      <h2 class="pacom-section-title">操作与权限拦截审计日志</h2>
                      <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                        <select class="pacom-select" name="auditActionCat" data-audit-cat aria-label="按行为类别筛选">
                          <option value="all" ${auditActionCat === 'all' ? 'selected' : ''}>全部操作类型</option>
                          <option value="control" ${auditActionCat === 'control' ? 'selected' : ''}>设备控制与场景</option>
                          <option value="alarm" ${auditActionCat === 'alarm' ? 'selected' : ''}>告警与工单处置</option>
                          <option value="deploy" ${auditActionCat === 'deploy' ? 'selected' : ''}>系统部署与点位</option>
                        </select>
                        <div class="pacom-tabs">
                          <button class="pacom-tab" aria-selected="${auditFilter === 'all'}" data-audit-filter="all">全部（${logs.length}）</button>
                          <button class="pacom-tab" aria-selected="${auditFilter === 'success'}" data-audit-filter="success">成功</button>
                          <button class="pacom-tab" aria-selected="${auditFilter === 'denied'}" data-audit-filter="denied">已拦截</button>
                        </div>
                      </div>
                    </div>
                    <div class="pacom-table-card">
                      <div class="pacom-table-wrap">
                        <table class="pacom-table">
                          <thead>
                            <tr>
                              <th>操作行为</th>
                              <th>目标资源</th>
                              <th>执行人</th>
                              <th>时间</th>
                              <th>结果</th>
                            </tr>
                          </thead>
                          <tbody>
                            ${visibleLogs
                              .map(
                                (l) => `
                                <tr>
                                  <td>
                                    <div style="font-weight:500;">${l.action}</div>
                                    ${l.detail ? `<div class="pacom-row-sub">${l.detail}</div>` : ''}
                                  </td>
                                  <td><code style="font-size:12px;">${l.target}</code></td>
                                  <td>${l.actor}</td>
                                  <td><span class="pacom-row-sub">${l.at.slice(0, 19).replace('T', ' ')}</span></td>
                                  <td>
                                    <span class="pacom-badge ${l.result === 'success' ? 'pacom-badge--online' : 'pacom-badge--critical'}">
                                      ${l.result === 'success' ? '成功' : l.result}
                                    </span>
                                  </td>
                                </tr>`
                              )
                              .join('')}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </section>`
            }
          </div>
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-atab]').forEach((btn) => {
      btn.addEventListener('click', () => {
        tab = btn.dataset.atab as AccountTab;
        profileNotice = '';
        errorMsg = '';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-msub]').forEach((btn) => {
      btn.addEventListener('click', () => {
        membersSubTab = (btn.dataset.msub as MembersSubTab) ?? 'directory';
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-new-group]')?.addEventListener('click', () => {
      showNewGroupForm = !showNewGroupForm;
      render();
    });

    root.querySelector<HTMLFormElement>('[data-role="new-group-form"]')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const fd = new FormData(e.currentTarget as HTMLFormElement);
      const name = String(fd.get('wgName') ?? '').trim();
      const role = String(fd.get('wgRole') ?? '运行值班员');
      const scope = String(fd.get('wgScope') ?? '').trim();
      if (!name || !scope) return;
      WORKGROUPS.push({
        id: `wg-${Date.now()}`,
        name,
        defaultRoleLabel: role,
        locationScope: scope,
        memberCount: 1,
        membersSummary: session.displayName,
        notifyChannel: '站内 + 邮件',
      });
      showNewGroupForm = false;
      profileNotice = `已创建工作组「${name}」（授权空间：${scope}）。`;
      render();
    });

    root.querySelector<HTMLFormElement>('[data-role="profile-form"]')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const fd = new FormData(e.currentTarget as HTMLFormElement);
      profileName = String(fd.get('displayName') ?? '').trim() || session.displayName;
      profileTitle = String(fd.get('jobTitle') ?? '').trim() || profileTitle;
      profilePhone = String(fd.get('phone') ?? '').trim() || profilePhone;
      profileNotice = `已更新个人资料：${profileName}（${profileTitle}）· 告警短信接收号 ${profilePhone}。`;
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-role="logout-btn"]')?.addEventListener('click', async () => {
      await adapter.logout();
      window.location.hash = '#login';
      onLoggedOut();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-switch-role]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!adapter.switchDemoRole) return;
        const next = await adapter.switchDemoRole(btn.dataset.switchRole as PlatformRole);
        onRoleChanged(next);
      });
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-invite]')?.addEventListener('click', () => {
      showInviteForm = !showInviteForm;
      render();
    });

    const mSearch = root.querySelector<HTMLInputElement>('[data-member-search]');
    mSearch?.addEventListener('input', (e) => {
      const target = e.currentTarget as HTMLInputElement;
      const pos = target.selectionStart ?? target.value.length;
      memberSearch = target.value;
      render();
      const next = root.querySelector<HTMLInputElement>('[data-member-search]');
      if (next) {
        next.focus();
        next.setSelectionRange(pos, pos);
      }
    });

    root.querySelector<HTMLSelectElement>('[data-role-filter]')?.addEventListener('change', (e) => {
      roleFilter = (e.currentTarget as HTMLSelectElement).value;
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-audit-filter]').forEach((btn) => {
      btn.addEventListener('click', () => {
        auditFilter = (btn.dataset.auditFilter as 'all' | 'success' | 'denied') ?? 'all';
        render();
      });
    });

    root.querySelector<HTMLSelectElement>('[data-audit-cat]')?.addEventListener('change', (e) => {
      auditActionCat = ((e.currentTarget as HTMLSelectElement).value as 'all' | 'control' | 'alarm' | 'deploy') ?? 'all';
      render();
    });

    root.querySelector<HTMLFormElement>('[data-role="invite-form"]')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      errorMsg = '';
      const fd = new FormData(e.currentTarget as HTMLFormElement);
      try {
        await adapter.inviteOrgMember(String(fd.get('email') ?? ''), String(fd.get('role')) as PlatformRole);
        showInviteForm = false;
        await refresh();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });
  }

  render();
}
