function strokeForSize(size: number): string {
  if (size >= 20) return '1.5';
  if (size >= 16) return '1.75';
  if (size >= 14) return '2';
  return '2.25';
}

export function renderIcon(name: IconName, size: 12 | 14 | 16 | 20 = 16, className = ''): string {
  const sw = strokeForSize(size);
  const cls = className ? ` class="${className}"` : '';
  return `<svg${cls} width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="flex-shrink:0;">${ICON_PATHS[name]}</svg>`;
}
