import type { SpatialTree, UserSession } from '@pacom/contracts';
import { E7F_IDS } from '../adapters';
import { renderIcon } from '../design-system/icons';

export type GlobalSpaceScope =
  | { level: 'all-projects' }
  | { level: 'project'; projectId: string }
  | { level: 'building'; projectId: string; buildingId: string }
  | { level: 'floor'; projectId: string; buildingId: string; floorId: string };

export type SpaceGranularity = 'project' | 'building' | 'floor';

let currentGlobalScope: GlobalSpaceScope = {
  level: 'floor',
  projectId: E7F_IDS.projectId,
  buildingId: E7F_IDS.buildingId,
  floorId: E7F_IDS.floorId,
};

export function getGlobalSpaceScope(): GlobalSpaceScope {
  return currentGlobalScope;
}

export function setGlobalSpaceScope(next: GlobalSpaceScope): GlobalSpaceScope {
  currentGlobalScope = next;
  return currentGlobalScope;
}

function escapeHtml(value: unknown): string {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function parseFloorOrder(name: string): number {
  const upper = name.trim().toUpperCase();
  if (upper === 'RF' || upper === 'R' || upper === 'ROOF' || upper.includes('屋面')) return 999;
  const m = upper.match(/(-?\d+)/);
  if (!m) return 0;
  const n = Number(m[1]);
  return upper.startsWith('B') ? -Math.abs(n) : n;
}

export function parseScopeValue(raw: string): GlobalSpaceScope {
  if (raw === 'all') return { level: 'all-projects' };
  const parts = raw.split(':');
  if (parts[0] === 'project' && parts[1]) return { level: 'project', projectId: parts[1] };
  if (parts[0] === 'building' && parts[1] && parts[2]) {
    return { level: 'building', projectId: parts[1], buildingId: parts[2] };
  }
  if (parts[0] === 'floor' && parts[1] && parts[2] && parts[3]) {
    return { level: 'floor', projectId: parts[1], buildingId: parts[2], floorId: parts[3] };
  }
  return { level: 'project', projectId: E7F_IDS.projectId };
}

export interface SpacePathOptions {
  tree: SpatialTree;
  session: UserSession;
  scope?: GlobalSpaceScope;
  maxGranularity?: SpaceGranularity;
  activeAlarmCount?: number;
  isOpen: boolean;
  searchKeyword: string;
}

function getEffectiveScope(scope: GlobalSpaceScope, tree: SpatialTree, maxGranularity: SpaceGranularity): GlobalSpaceScope {
  if (maxGranularity === 'project') {
    if (scope.level === 'all-projects') return { level: 'project', projectId: tree.projects[0]?.id ?? E7F_IDS.projectId };
    return { level: 'project', projectId: scope.projectId };
  }
  if (maxGranularity === 'building' && scope.level === 'floor') {
    return { level: 'building', projectId: scope.projectId, buildingId: scope.buildingId };
  }
  return scope;
}

export function renderSpacePathControl(opts: SpacePathOptions): string {
  const { tree, session, isOpen, searchKeyword } = opts;
  const maxGranularity = opts.maxGranularity ?? 'floor';
  const activeAlarmCount = opts.activeAlarmCount ?? 0;
  const memberZoneLimit = session.scope.allowedZoneIds?.length ? session.scope.allowedZoneIds : null;
  const allowedFloors = tree.floors.filter((f) => session.scope.allowedFloorIds.includes(f.id));
  const topology =
    memberZoneLimit || (tree.projects.length <= 1 && tree.buildings.length <= 1 && allowedFloors.length <= 1)
      ? 'floors-only'
      : tree.projects.length > 1
        ? 'multi-project'
        : tree.buildings.length > 1
          ? 'single-project-multi-building'
          : 'single-building';

  const canViewAllProjects = topology === 'multi-project' && maxGranularity !== 'project';
  const canViewProject = topology === 'multi-project' || topology === 'single-project-multi-building';
  const canViewBuilding = topology !== 'floors-only' && maxGranularity !== 'project';
  const isStatic =
    (maxGranularity === 'project' && tree.projects.length <= 1) ||
    (topology === 'floors-only' && allowedFloors.length <= 1);

  const scope = getEffectiveScope(opts.scope ?? currentGlobalScope, tree, maxGranularity);
  const curProj = scope.level === 'all-projects' ? null : tree.projects.find((p) => p.id === scope.projectId) ?? tree.projects[0];
  const curBld = scope.level === 'building' || scope.level === 'floor' ? tree.buildings.find((b) => b.id === scope.buildingId) : null;
  const curFloor = scope.level === 'floor' ? tree.floors.find((f) => f.id === scope.floorId) : null;

  const parts: string[] = [];
  if (scope.level === 'all-projects') {
    parts.push(`全部项目（${tree.projects.length}）`);
  } else if (scope.level === 'project') {
    parts.push(escapeHtml(curProj?.name ?? '广实2号园'));
  } else if (scope.level === 'building') {
    if (curProj) parts.push(`<span class="pacom-path-muted">${escapeHtml(curProj.name)}</span>`);
    parts.push(escapeHtml(curBld?.name ?? 'E栋'));
  } else {
    if (curProj && topology !== 'floors-only') parts.push(`<span class="pacom-path-muted">${escapeHtml(curProj.name)}</span>`);
    if (curBld && canViewBuilding) parts.push(`<span class="pacom-path-muted">${escapeHtml(curBld.name)}</span>`);
    const floorText = !canViewBuilding && curBld ? `${curBld.name} ${curFloor?.name ?? '7F'}` : (curFloor?.name ?? '7F');
    parts.push(escapeHtml(floorText));
  }

  const sep = `<span class="pacom-path-muted" style="margin:0 3px;">·</span>`;
  const triggerHtml = isStatic
    ? `<span class="pacom-path-trigger is-static">${parts.join(sep)}</span>`
    : `<button type="button" class="pacom-path-trigger" data-global-space-toggle="1" aria-expanded="${isOpen}" aria-haspopup="dialog" title="切换项目 / 楼宇 / 楼层">
        <span>${parts.join(sep)}</span>
        <span style="display:inline-flex; color:var(--pacom-text-secondary);">${renderIcon('chevron-down', 12)}</span>
      </button>`;

  if (!isOpen || isStatic) {
    return `<span class="pacom-title-slash" aria-hidden="true">/</span><div class="pacom-path-wrap">${triggerHtml}</div>`;
  }

  const q = searchKeyword.trim().toLowerCase();
  const activeProjectId = scope.level === 'all-projects' ? (tree.projects[0]?.id ?? E7F_IDS.projectId) : scope.projectId;
  const activeBuildingId =
    scope.level === 'building' || scope.level === 'floor'
      ? scope.buildingId
      : (tree.buildings.find((b) => b.projectId === activeProjectId)?.id ?? E7F_IDS.buildingId);

  const matchedProjects = tree.projects.filter((p) => !q || p.name.toLowerCase().includes(q));
  const matchedBuildings = tree.buildings.filter((b) => b.projectId === activeProjectId && (!q || b.name.toLowerCase().includes(q)));
  const matchedFloors = [...tree.floors.filter((f) => f.buildingId === activeBuildingId)]
    .sort((a, b) => parseFloorOrder(b.name) - parseFloorOrder(a.name))
    .filter((f) => !q || f.name.toLowerCase().includes(q));

  const showProjectCol = maxGranularity === 'project' || tree.projects.length > 1;
  const showBuildingCol = maxGranularity !== 'project' && canViewProject;
  const showFloorCol = maxGranularity === 'floor';

  return `
    <span class="pacom-title-slash" aria-hidden="true">/</span>
    <div class="pacom-path-wrap" data-role="global-space-wrap">
      ${triggerHtml}
      <div class="pacom-space-popover pacom-path-popover" role="dialog" aria-label="全局空间切换" data-role="global-space-pop">
        <div class="pacom-space-pop-head">
          ${renderIcon('search', 14)}
          <input type="text" name="globalSpaceSearch" data-global-space-search placeholder="检索园区、楼宇或楼层…" value="${escapeHtml(searchKeyword)}" aria-label="检索空间" />
          <button type="button" class="pacom-drawer-close" style="width:24px; height:24px;" data-global-space-toggle="1" aria-label="关闭">${renderIcon('x', 14)}</button>
        </div>
        <div class="pacom-space-pop-cols">
          ${
            showProjectCol
              ? `
              <div class="pacom-space-pop-col">
                <div class="pacom-space-pop-label">项目 / 园区</div>
                ${
                  canViewAllProjects
                    ? `<button type="button" class="pacom-space-pop-item ${scope.level === 'all-projects' ? 'is-active' : ''}" data-global-space-pick="all">
                        <span>全部项目（${tree.projects.length}）</span>
                        ${scope.level === 'all-projects' ? renderIcon('check', 14) : ''}
                      </button>`
                    : ''
                }
                ${matchedProjects
                  .map((p) => {
                    const isAct = scope.level === 'project' && scope.projectId === p.id;
                    return `<button type="button" class="pacom-space-pop-item ${isAct ? 'is-active' : ''}" data-global-space-pick="project:${escapeHtml(p.id)}">
                      <span>${escapeHtml(p.name)}</span>
                      ${isAct ? renderIcon('check', 14) : renderIcon('chevron-right', 12)}
                    </button>`;
                  })
                  .join('')}
              </div>`
              : ''
          }
          ${
            showBuildingCol
              ? `
              <div class="pacom-space-pop-col">
                <div class="pacom-space-pop-label">${escapeHtml(tree.projects.find((p) => p.id === activeProjectId)?.name ?? '园区')} · 楼宇</div>
                <button type="button" class="pacom-space-pop-item ${scope.level === 'project' ? 'is-active' : ''}" data-global-space-pick="project:${escapeHtml(activeProjectId)}">
                  <span>全园区</span>
                  ${scope.level === 'project' ? renderIcon('check', 14) : ''}
                </button>
                ${matchedBuildings
                  .map((b) => {
                    const isAct = scope.level === 'building' && scope.buildingId === b.id;
                    return `<button type="button" class="pacom-space-pop-item ${isAct ? 'is-active' : ''}" data-global-space-pick="building:${escapeHtml(b.projectId)}:${escapeHtml(b.id)}">
                      <span style="display:inline-flex; align-items:center; gap:6px;">
                        <span>${escapeHtml(b.name)}</span>
                        ${b.id === E7F_IDS.buildingId && activeAlarmCount > 0 ? '<span class="pacom-elev-dot"></span>' : ''}
                      </span>
                      ${isAct ? renderIcon('check', 14) : renderIcon('chevron-right', 12)}
                    </button>`;
                  })
                  .join('')}
              </div>`
              : ''
          }
          ${
            showFloorCol
              ? `
              <div class="pacom-space-pop-col">
                <div class="pacom-space-pop-label">${escapeHtml(tree.buildings.find((b) => b.id === activeBuildingId)?.name ?? '楼宇')} · 楼层</div>
                ${
                  canViewBuilding
                    ? `<button type="button" class="pacom-space-pop-item ${scope.level === 'building' && scope.buildingId === activeBuildingId ? 'is-active' : ''}" data-global-space-pick="building:${escapeHtml(activeProjectId)}:${escapeHtml(activeBuildingId)}">
                        <span>整栋</span>
                        ${scope.level === 'building' && scope.buildingId === activeBuildingId ? renderIcon('check', 14) : ''}
                      </button>`
                    : ''
                }
                ${matchedFloors
                  .map((f) => {
                    const allowed = session.scope.allowedFloorIds.includes(f.id);
                    const isAct = scope.level === 'floor' && scope.floorId === f.id;
                    const hasAlarm = f.id === E7F_IDS.floorId && activeAlarmCount > 0;
                    return `<button type="button" class="pacom-space-pop-item ${isAct ? 'is-active' : ''}" style="${allowed ? '' : 'opacity:0.5;'}" data-global-space-pick="floor:${escapeHtml(activeProjectId)}:${escapeHtml(activeBuildingId)}:${escapeHtml(f.id)}">
                      <span style="display:inline-flex; align-items:center; gap:6px;">
                        <span>${escapeHtml(f.name)}</span>
                        ${hasAlarm ? '<span class="pacom-elev-dot"></span>' : ''}
                      </span>
                      <span class="pacom-row-sub" style="font-size:11px;">${isAct ? renderIcon('check', 14) : allowed ? (f.plan ? '2D' : '待部署') : '未授权'}</span>
                    </button>`;
                  })
                  .join('')}
              </div>`
              : ''
          }
        </div>
      </div>
    </div>
  `;
}

export function bindSpacePathControl(
  root: HTMLElement,
  handlers: {
    onToggle: () => void;
    onSearch: (kw: string) => void;
    onPick: (next: GlobalSpaceScope) => void;
  }
): void {
  root.querySelectorAll<HTMLButtonElement>('[data-global-space-toggle]').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      handlers.onToggle();
    });
  });

  const searchEl = root.querySelector<HTMLInputElement>('[data-global-space-search]');
  searchEl?.addEventListener('input', (e) => {
    handlers.onSearch((e.currentTarget as HTMLInputElement).value);
  });

  root.querySelectorAll<HTMLButtonElement>('[data-global-space-pick]').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const raw = btn.dataset.globalSpacePick;
      if (!raw) return;
      const next = setGlobalSpaceScope(parseScopeValue(raw));
      handlers.onPick(next);
    });
  });
}
