  async upsertFloor(input: {
    id?: string;
    buildingId: string;
    kind: FloorKind;
    level: number;
    name: string;
    areaSqm?: number | null;
    planImageUrl?: string | null;
  }): Promise<FloorNode> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权维护楼层`);
    const now = new Date().toISOString();
    let fl = input.id ? this.spatial.floors.find((f) => f.id === input.id) : undefined;
    if (fl) {
      fl.name = input.name.trim() || fl.name;
      fl.kind = input.kind;
      fl.level = input.level;
      if (input.areaSqm !== undefined) fl.areaSqm = input.areaSqm;
      if (input.planImageUrl !== undefined) {
        fl.plan = input.planImageUrl
          ? {
              floorId: fl.id,
              imageUrl: input.planImageUrl,
              planVersion: (fl.plan?.planVersion ?? 0) + 1,
              updatedAt: now,
            }
          : null;
      }
    } else {
      const id = `floor-${input.buildingId.slice(-6)}-${input.kind}-${Math.abs(input.level)}-${Date.now().toString(36).slice(-3)}`;
      fl = {
        id,
        buildingId: input.buildingId,
        kind: input.kind,
        level: input.level,
        name: input.name.trim() || `${input.level}F`,
        areaSqm: input.areaSqm ?? null,
        plan: input.planImageUrl
          ? { floorId: id, imageUrl: input.planImageUrl, planVersion: 1, updatedAt: now }
          : null,
      };
      this.spatial.floors.push(fl);
      if (this.activeSession && !this.activeSession.scope.allowedFloorIds.includes(fl.id)) {
        this.activeSession.scope.allowedFloorIds.push(fl.id);
      }
    }
    this.persistSpatial();
    this.record('REST', 'upsertFloor', 'PUT /api/v1/floors', { id: fl.id, name: fl.name, hasPlan: Boolean(fl.plan) });
    this.pushAudit('floor.upsert', fl.id, 'success', fl.name);
    return structuredClone(fl);
  }

