  async copyZonesToFloors(sourceFloorId: string, targetFloorIds: string[]): Promise<number> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权复制功能区`);
    const srcFloor = this.spatial.floors.find((f) => f.id === sourceFloorId);
    const srcZones = this.spatial.zones.filter((z) => z.floorId === sourceFloorId);
    if (!srcFloor || srcZones.length === 0) return 0;
    let added = 0;
    for (const tid of targetFloorIds) {
      if (tid === sourceFloorId) continue;
      const tFloor = this.spatial.floors.find((f) => f.id === tid);
      if (!tFloor) continue;
      const existingNames = new Set(this.spatial.zones.filter((z) => z.floorId === tid).map((z) => z.name));
      for (const sz of srcZones) {
        const cleanBase = sz.name.replace(new RegExp(`^${srcFloor.name}\\s*`, 'i'), '');
        const nextName = `${tFloor.name} ${cleanBase}`.trim();
        if (existingNames.has(nextName)) continue;
        this.spatial.zones.push({
          id: `zone-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
          floorId: tid,
          name: nextName,
          category: sz.category,
        });
        existingNames.add(nextName);
        added += 1;
      }
    }
    if (added > 0) this.persistSpatial();
    this.record('REST', 'copyZonesToFloors', 'POST /api/v1/zones/copy', { sourceFloorId, targetCount: targetFloorIds.length, added });
    return added;
  }

  async getFloorDevices(floorId: string): Promise<DeviceEntity[]> {
    const session = this.requireSession();
    if (!session.scope.allowedFloorIds.includes(floorId)) {
      const err = { code: 'FORBIDDEN', status: 403, message: `当前角色「${session.roleLabel}」无权访问目标楼层` };
      this.record('REST', 'getFloorDevices', `GET /api/v1/floors/${floorId}/devices`, err);
      this.pushAudit('floor.read', floorId, 'denied', err.message);
      throw new Error(`403 FORBIDDEN: ${err.message}`);
    }
    if (floorId !== E7F_IDS.floorId) return [];
    let list = structuredClone(this.devices);
    if (session.scope.allowedZoneIds?.length) {
      list = list.filter((d) => d.logicalZoneId && session.scope.allowedZoneIds!.includes(d.logicalZoneId));
    }
    this.record('REST', 'getFloorDevices', `GET /api/v1/floors/${floorId}/devices`, { count: list.length });
    return list;
  }

  async dispatchControlBatch(req: CreateControlBatchRequest): Promise<ControlBatch> {
    const session = this.requireSession();
    if (!session.scope.canControlDevices || !session.scope.allowedFloorIds.includes(req.floorId)) {
      throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权下发控制指令`);
    }
    const batchId = `batch-e7f-${Date.now().toString(36)}`;
    const batch: ControlBatch = {
      batchId,
      floorId: req.floorId,
      createdBy: session.userId,
      createdAt: new Date().toISOString(),
      receipts: req.targets.map((t) => ({ deviceId: t.deviceId, command: t.command, targetValue: t.targetValue, status: 'queued' })),
    };
    this.batches.set(batchId, batch);
    this.record('REST', 'dispatchControlBatch', 'POST /api/v1/control/batches', batch, req);
    this.pushAudit('control.dispatch', batchId, 'success', `下发 ${req.targets.length} 台设备`);

    batch.receipts.forEach((receipt, idx) => {
      const device = this.devices.find((d) => d.id === receipt.deviceId);
      setTimeout(() => {
        receipt.status = 'dispatched';
        receipt.dispatchedAt = new Date().toISOString();
        this.emit({ type: 'control.receipt.updated', batchId, deviceId: receipt.deviceId, status: 'dispatched', at: receipt.dispatchedAt });
      }, 280 + idx * 120);

      setTimeout(() => {
        const verifiedAt = new Date().toISOString();
        if (!device || device.connectivity === 'offline') {
          receipt.status = 'timeout';
          receipt.errorCode = 'GATEWAY_READBACK_TIMEOUT';
          receipt.errorMessage = '设备离线，网关未收到回读确认';
          receipt.verifiedAt = verifiedAt;
        } else {
          receipt.status = 'verified_success';
          receipt.observedValue = receipt.targetValue;
          receipt.verifiedAt = verifiedAt;
          this.applyObservedTelemetry(device, receipt.command, receipt.targetValue, verifiedAt);
        }
        this.emit({ type: 'control.receipt.updated', batchId, deviceId: receipt.deviceId, status: receipt.status, observedValue: receipt.observedValue, at: verifiedAt });
      }, 900 + idx * 220);
    });

    return structuredClone(batch);
  }

  private applyObservedTelemetry(device: DeviceEntity, command: string, value: number | boolean | string, at: string): void {
    if (command === 'lighting.dimming' && device.telemetry.dimming) {
      device.telemetry.dimming = { ...device.telemetry.dimming, value, collectedAt: at, stale: false };
      if (device.telemetry.power) device.telemetry.power = { ...device.telemetry.power, value: Number(value) > 0, collectedAt: at, stale: false };
    } else if ((command === 'lighting.power' || command === 'hvac.power') && device.telemetry.power) {
      device.telemetry.power = { ...device.telemetry.power, value, collectedAt: at, stale: false };
    } else if (command === 'hvac.setpoint' && device.telemetry.setpoint) {
      device.telemetry.setpoint = { ...device.telemetry.setpoint, value, collectedAt: at, stale: false };
    }
    this.emit({ type: 'telemetry.updated', floorId: device.floorId, deviceId: device.id, collectedAt: at, values: { [command]: value } });
  }

