  async acknowledgeAlarm(alarmId: string, note?: string): Promise<AlarmRecord> {
    const session = this.requireSession();
    if (!session.scope.canManageAlarms) {
      const msg = `角色「${session.roleLabel}」仅可查看告警，无权确认`;
      this.pushAudit('alarm.acknowledge', alarmId, 'denied', msg);
      throw new Error(`403 FORBIDDEN: ${msg}`);
    }
    const target = this.alarms.find((a) => a.id === alarmId);
    if (!target) throw new Error(`404 NOT_FOUND: 告警 ${alarmId} 不存在`);
    target.status = 'acknowledged';
    target.acknowledgedAt = new Date().toISOString();
    target.acknowledgedBy = session.displayName;
    this.record('REST', 'acknowledgeAlarm', `POST /api/v1/alarms/${alarmId}/acknowledge`, target, { note });
    this.pushAudit('alarm.acknowledge', alarmId, 'success', note);
    this.emit({ type: 'alarm.changed', floorId: target.floorId, alarmId, status: 'acknowledged', at: target.acknowledgedAt });
    return structuredClone(target);
  }

