  async createWorkOrder(input: { floorId: string; deviceId?: string; alarmId?: string; title: string; description: string }): Promise<WorkOrderRecord> {
    const session = this.requireSession();
    if (!session.scope.canManageAlarms) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权创建工单`);
    const now = new Date().toISOString();
    const wo: WorkOrderRecord = { id: `wo-e7f-${Date.now().toString(36)}`, projectId: E7F_IDS.projectId, buildingId: E7F_IDS.buildingId, floorId: input.floorId, deviceId: input.deviceId ?? null, alarmId: input.alarmId ?? null, title: input.title, description: input.description, status: 'open', assigneeId: null, createdAt: now, updatedAt: now };
    this.workOrders.unshift(wo);
    if (input.alarmId) {
      const alm = this.alarms.find((a) => a.id === input.alarmId);
      if (alm) alm.workOrderId = wo.id;
    }
    this.record('REST', 'createWorkOrder', 'POST /api/v1/work-orders', wo, input);
    this.pushAudit('work_order.create', wo.id, 'success', wo.title);
    return structuredClone(wo);
  }

