  async updateDevicePlanPoint(req: UpdatePlanPointRequest): Promise<DeviceEntity> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) {
      this.pushAudit('device.plan_point', req.deviceId, 'denied', '无系统部署编辑权限');
      throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权编辑图纸标点`);
    }
    const device = this.devices.find((d) => d.id === req.deviceId);
    if (!device) throw new Error(`404 NOT_FOUND: 设备 ${req.deviceId} 不存在`);
    if (device.version !== req.expectedVersion) throw new Error(`409 CONFLICT: 设备版本已变更为 v${device.version}，请刷新后重试`);
    device.planPoint = { floorId: req.floorId, planVersion: req.planVersion, x: Number(req.x.toFixed(4)), y: Number(req.y.toFixed(4)) };
    device.version += 1;
    this.record('REST', 'updateDevicePlanPoint', `PATCH /api/v1/devices/${req.deviceId}/plan-point`, device, req);
    this.pushAudit('device.plan_point', req.deviceId, 'success', `坐标更新 (${device.planPoint.x}, ${device.planPoint.y})`);
    return structuredClone(device);
  }

  async updateDeviceHardwareBinding(req: UpdateHardwareBindingRequest): Promise<DeviceEntity> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权修改硬件绑定`);
    const device = this.devices.find((d) => d.id === req.deviceId);
    if (!device) throw new Error(`404 NOT_FOUND: 设备 ${req.deviceId} 不存在`);
    if (device.version !== req.expectedVersion) throw new Error(`409 CONFLICT: 设备版本冲突（当前 v${device.version}）`);
    const now = new Date().toISOString();
    device.physicalInstalled = req.physicalInstalled;
    device.physicalVerifiedAt = req.physicalInstalled ? now : null;
    device.hardwareBinding = { gatewayId: req.gatewayId, protocol: req.protocol, networkAddress: req.networkAddress, portOrChannel: req.portOrChannel, boundAt: now, boundBy: session.displayName };
    device.version += 1;
    this.record('REST', 'updateDeviceHardwareBinding', `PUT /api/v1/devices/${req.deviceId}/hardware-binding`, device, req);
    this.pushAudit('device.hardware_binding', req.deviceId, 'success', `${req.protocol} ${req.networkAddress}`);
    return structuredClone(device);
  }

