    const scene: SceneDefinition = { id: `scn-e7f-${Date.now().toString(36)}`, projectId: req.projectId, floorId: req.floorId, name: req.name, description: req.description, enabled: true, scheduleSummary: '手动触发', actions: req.actions, lastExecutedAt: null };
