  async executeScene(sceneId: string): Promise<ControlBatch> {
    const scene = this.scenes.find((s) => s.id === sceneId);
    if (!scene) throw new Error(`404 NOT_FOUND: 场景 ${sceneId} 不存在`);
    const batch = await this.dispatchControlBatch({ floorId: scene.floorId, idempotencyKey: `scene-${sceneId}-${Date.now()}`, targets: scene.actions, reason: `触发场景：${scene.name}` });
    scene.lastExecutedAt = new Date().toISOString();
    scene.lastBatchId = batch.batchId;
    return batch;
  }

