  async saveWorkCalendar(_projectId: string, workdayStart: string, workdayEnd: string, expectedVersion: number): Promise<WorkCalendarConfig> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权修改运行日历`);
    if (this.calendar.version !== expectedVersion) throw new Error(`409 CONFLICT: 运行日历已被更新至 v${this.calendar.version}`);
    if (workdayStart >= workdayEnd) throw new Error('400 BAD_REQUEST: 上班时间必须早于下班时间');
    this.calendar = { ...this.calendar, workdayStart, workdayEnd, version: this.calendar.version + 1, updatedAt: new Date().toISOString() };
    this.record('REST', 'saveWorkCalendar', 'PUT /api/v1/settings/calendar', this.calendar, { workdayStart, workdayEnd, expectedVersion });
    this.pushAudit('settings.calendar', E7F_IDS.projectId, 'success', `${workdayStart}-${workdayEnd}`);
    return structuredClone(this.calendar);
  }

  async toggleRuntimeRule(ruleId: string, enabled: boolean, expectedVersion: number): Promise<RuntimeRuleItem> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权启停运行规则`);
    const rule = this.rules.find((r) => r.id === ruleId);
    if (!rule) throw new Error(`404 NOT_FOUND: 规则 ${ruleId} 不存在`);
    if (rule.version !== expectedVersion) throw new Error(`409 CONFLICT: 规则版本冲突（当前 v${rule.version}）`);
    rule.enabled = enabled;
    rule.version += 1;
    rule.lastAppliedAt = new Date().toISOString();
    this.record('REST', 'toggleRuntimeRule', `PATCH /api/v1/settings/rules/${ruleId}`, rule, { enabled, expectedVersion });
    this.pushAudit('settings.rule_toggle', ruleId, 'success', enabled ? '启用' : '停用');
    return structuredClone(rule);
  }

