  subscribeFloorEvents(floorId: string, onEvent: (event: RealtimeEvent) => void): UnsubscribeFn {
    if (floorId !== E7F_IDS.floorId) return () => {};
    this.listeners.add(onEvent);
    return () => { this.listeners.delete(onEvent); };
  }

  private emit(event: RealtimeEvent): void {
    this.record('WS', event.type, `WS /ws/v1/stream?floorId=${E7F_IDS.floorId}`, event);
    this.listeners.forEach((fn) => fn(event));
  }
