  function missingFloorSpecs(bld: SpatialTree['buildings'][number]): Array<{ kind: 'above' | 'below' | 'roof'; level: number; name: string }> {
    const existingKeys = new Set(
      sortedBuildingFloors(bld.id).map((f) => normalizeFloorMatchKey(f.name) ?? f.name.toUpperCase())
    );
    const missing: Array<{ kind: 'above' | 'below' | 'roof'; level: number; name: string }> = [];
    for (let i = 1; i <= bld.aboveFloors; i += 1) {
      const name = `${i}F`;
      if (!existingKeys.has(name)) missing.push({ kind: 'above', level: i, name });
    }
    for (let b = 1; b <= bld.belowFloors; b += 1) {
      const name = `B${b}`;
      if (!existingKeys.has(name)) missing.push({ kind: 'below', level: -b, name });
    }
    if (bld.hasRoof && !existingKeys.has('RF')) {
      missing.push({ kind: 'roof', level: 99, name: 'RF' });
    }
    return missing;
  }

  async function fillMissingFloorsForBuilding(bldId: string): Promise<number> {
    const bld = tree.buildings.find((b) => b.id === bldId);
    if (!bld) return 0;
    const specs = missingFloorSpecs(bld);
    for (const s of specs) {
      await adapter.upsertFloor?.({ buildingId: bld.id, kind: s.kind, level: s.level, name: s.name });
    }
    return specs.length;
  }

