    function stageBatchFiles(bldId: string, files: File[]): void {
      if (!bldId || files.length === 0) return;
      const bldFloors = sortedBuildingFloors(bldId);
      const floorByKey = new Map<string, SpatialTree['floors'][number]>();
      bldFloors.forEach((f) => {
        const key = normalizeFloorMatchKey(f.name) ?? f.name.toUpperCase();
        floorByKey.set(key, f);
      });
      pendingBatchUploads = files.map((file, idx) => {
        const key = normalizeFloorMatchKey(file.name);
        const target = key ? floorByKey.get(key) : undefined;
        return { id: `bu-${Date.now().toString(36)}-${idx}`, file, matchedFloorId: target?.id ?? null };
      });
      showBatchPanel = true;
      render();
    }

